// ── Projeção de Férias
function ProjecaoFerias({ project, colaboradores, adminAuth, liderAuth, onBack, onSave, ferias, dark, onToggleTheme }) {
  const S = getStyles(dark);
  // Líder e Gerencial podem agendar férias e reordenar a equipe — é trabalho do líder no dia a dia.
  const podeEditar = adminAuth || liderAuth;

  // ferias = array of { colabId, dataInicio, dataRetorno(auto), cobertura, ordem }
  const [lista, setLista] = useState(() => {
    // Merge colaboradores with existing ferias data
    return colaboradores.map(c => {
      const existing = (ferias||[]).find(f=>f.colabId===c.id);
      return {
        colabId: c.id,
        nome: c.nome,
        cargo: c.cargo,
        turno: c.turno,
        foto: c.foto||"",
        dataContratacao: c.dataContratacao||"",
        dataInicio: existing?.dataInicio||"",
        dataRetorno: existing?.dataRetorno||"",
        cobertura: existing?.cobertura||"",
        ordem: existing?.ordem ?? colaboradores.indexOf(c),
      };
    }).sort((a,b)=>a.ordem-b.ordem);
  });

  const [editId, setEditId] = useState(null);
  const [saving, setSaving] = useState(false);

  function calcRetorno(inicio) {
    if(!inicio) return "";
    try {
      const d = new Date(inicio+"T12:00:00");
      d.setDate(d.getDate()+30);
      return d.toISOString().split("T")[0];
    } catch { return ""; }
  }

  function calcPeriodoAquisitivo(dataContratacao) {
    if(!dataContratacao) return null;
    try {
      const contrat = new Date(dataContratacao+"T12:00:00");
      const hoje = new Date();
      const meses = (hoje.getFullYear()-contrat.getFullYear())*12 + (hoje.getMonth()-contrat.getMonth());
      const completo = meses >= 12;
      return { meses, completo };
    } catch { return null; }
  }

  function fmtD(d) {
    if(!d) return "--";
    try { return new Date(d+"T12:00:00").toLocaleDateString("pt-BR"); } catch { return d; }
  }

  function alertaFerias(item) {
    if(!item.dataInicio) return null;
    const hoje = new Date();
    const inicio = new Date(item.dataInicio+"T12:00:00");
    const diff = Math.floor((inicio-hoje)/86400000);
    if(diff < 0) return null; // já começou
    if(diff <= 2) return { tipo:"urgente", msg:`⚠️ Férias em ${diff===0?"hoje":diff===1?"amanhã":diff+" dias"}!` };
    if(diff <= 7) return { tipo:"aviso", msg:`📅 Férias em ${diff} dias` };
    return null;
  }

  const updateItem = (colabId, fields) => {
    setLista(prev => prev.map(item => {
      if(item.colabId !== colabId) return item;
      const updated = {...item, ...fields};
      if(fields.dataInicio !== undefined) {
        updated.dataRetorno = calcRetorno(fields.dataInicio);
      }
      return updated;
    }));
  };

  const moveUp = (idx) => {
    if(idx===0) return;
    const newList = [...lista];
    [newList[idx-1], newList[idx]] = [newList[idx], newList[idx-1]];
    newList.forEach((item,i) => item.ordem=i);
    setLista(newList);
  };

  const moveDown = (idx) => {
    if(idx===lista.length-1) return;
    const newList = [...lista];
    [newList[idx], newList[idx+1]] = [newList[idx+1], newList[idx]];
    newList.forEach((item,i) => item.ordem=i);
    setLista(newList);
  };

  const salvar = async () => {
    setSaving(true);
    await onSave(lista);
    setSaving(false);
    setEditId(null);
  };

  // PDF Projeção
  const gerarPDF = () => {
    const hoje = new Date().toLocaleDateString("pt-BR");
    const rows = lista.map(item => {
      const pa = calcPeriodoAquisitivo(item.dataContratacao);
      const alerta = alertaFerias(item);
      return `<tr>
        <td><strong>${item.nome}</strong><br><span style="font-size:11px;color:#64748b">${item.cargo}</span></td>
        <td>${item.dataInicio?fmtD(item.dataInicio):"—"}</td>
        <td>${item.dataRetorno?fmtD(item.dataRetorno):"—"}</td>
        <td>${item.cobertura||"—"}</td>
        <td>${pa?`${pa.meses}m ${pa.completo?"✅":"⏳"}`:"—"}</td>
        <td style="color:${alerta?.tipo==="urgente"?"#dc2626":"#d97706"}">${alerta?.msg||"—"}</td>
      </tr>`;
    }).join("");

    const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">
    <title>Projeção Férias ${project.id}</title>
    <style>body{font-family:'Segoe UI',Arial,sans-serif;padding:20px;color:#1e293b}
    .header{background:linear-gradient(135deg,#1a1040,#0f0820);color:#fff;padding:20px;border-radius:12px;margin-bottom:16px}
    table{width:100%;border-collapse:collapse;font-size:12px}
    th{background:#1e293b;color:#fff;padding:8px 10px;text-align:left}
    td{padding:8px 10px;border-bottom:1px solid #f1f5f9}
    @media print{@page{margin:12mm}}</style></head>
    <body>
    <div class="no-print" style="margin-bottom:12px"><button onclick="window.print()" style="background:#1d4ed8;color:#fff;border:none;border-radius:8px;padding:10px 24px;font-size:14px;font-weight:700;cursor:pointer">🖨️ Imprimir / PDF</button></div>
    <div class="header"><h1 style="margin:0 0 4px;font-size:18px">🏖️ Projeção de Férias</h1>
    <p style="margin:0;font-size:12px;opacity:.8">${project.id} — ${project.name||""} · Gerado em ${hoje}</p></div>
    <table><thead><tr><th>Colaborador</th><th>Início</th><th>Retorno</th><th>Cobertura</th><th>Período Aq.</th><th>Alerta</th></tr></thead>
    <tbody>${rows}</tbody></table>
    <div style="margin-top:14px;font-size:10px;color:#94a3b8;text-align:center">MokLog CheckTest © Moked Consulting Security · ${project.id}</div>
    </body></html>`;

    const blob = new Blob([html],{type:"text/html"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href=url; a.download=`ferias_${project.id}_${new Date().toLocaleDateString("sv-SE")}.html`;
    a.click(); URL.revokeObjectURL(url);
  };

  return (
    <div style={S.page}>
      <div style={S.wrap}>
        <div style={{position:"sticky",top:0,zIndex:10,...S.headerBg,padding:"14px 16px"}}>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <button onClick={onBack} style={S.backBtn}>← Voltar</button>
            <div style={{flex:1}}>
              <div style={{fontSize:15,fontWeight:800,...S.txtPrimary}}>🏖️ Projeção de Férias</div>
              <div style={{fontSize:11,...S.txtSecondary}}>{project.id} · {lista.length} colaborador(es)</div>
            </div>
            <button onClick={gerarPDF} style={{...S.btnSm,color:"#a855f7",border:"1px solid #a855f744",fontSize:10}}>📄 PDF</button>
            <button onClick={onToggleTheme} style={{background:"transparent",border:`1px solid ${dark?"#1e293b":"#cbd5e1"}`,borderRadius:8,padding:"5px 8px",cursor:"pointer",fontSize:13,...S.txtSecondary}}>{dark?"☀️":"🌙"}</button>
          </div>
        </div>

        <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:8}}>
          {lista.map((item,idx) => {
            const pa = calcPeriodoAquisitivo(item.dataContratacao);
            const alerta = alertaFerias(item);
            const tc = TURNO_CONFIG[item.turno] || TURNO_CONFIG["Diurno"];
            const isEditing = editId===item.colabId;

            return (
              <div key={item.colabId} style={{...S.card, border:`2px solid ${alerta?.tipo==="urgente"?"#ef444444":alerta?"#f59e0b33":dark?"#0f172a":"#e2e8f0"}`}}>
                <div style={{display:"flex",alignItems:"center",gap:10}}>
                  {/* Foto */}
                  <div style={{width:44,height:44,borderRadius:10,overflow:"hidden",border:`2px solid ${tc.badge}44`,flexShrink:0,background:dark?"#0f172a":"#f1f5f9",display:"flex",alignItems:"center",justifyContent:"center"}}>
                    {item.foto?<img src={item.foto} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>:<span style={{fontSize:20}}>👤</span>}
                  </div>
                  {/* Info */}
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{fontSize:13,fontWeight:700,...S.txtPrimary,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{item.nome}</div>
                    <div style={{fontSize:11,...S.txtSecondary}}>{item.cargo}</div>
                    <div style={{display:"flex",gap:5,marginTop:3,flexWrap:"wrap",alignItems:"center"}}>
                      <span style={{fontSize:9,color:tc.badge,background:tc.bg,padding:"1px 6px",borderRadius:4,fontWeight:700}}>{tc.icon} {item.turno}</span>
                      {pa && <span style={{fontSize:9,color:pa.completo?"#22c55e":"#f59e0b",fontWeight:700}}>{pa.completo?"✅ Aquisitivo OK":`⏳ ${pa.meses}m/12`}</span>}
                    </div>
                  </div>
                  {/* Reorder buttons — líder ou gerencial */}
                  {podeEditar && (
                    <div style={{display:"flex",flexDirection:"column",gap:2,flexShrink:0}}>
                      <button onClick={()=>moveUp(idx)} disabled={idx===0}
                        style={{background:"transparent",border:`1px solid ${dark?"#1e293b":"#e2e8f0"}`,color:idx===0?dark?"#1e293b":"#e2e8f0":dark?"#64748b":"#94a3b8",borderRadius:4,width:24,height:22,cursor:idx===0?"not-allowed":"pointer",fontSize:11,display:"flex",alignItems:"center",justifyContent:"center"}}>↑</button>
                      <button onClick={()=>moveDown(idx)} disabled={idx===lista.length-1}
                        style={{background:"transparent",border:`1px solid ${dark?"#1e293b":"#e2e8f0"}`,color:idx===lista.length-1?dark?"#1e293b":"#e2e8f0":dark?"#64748b":"#94a3b8",borderRadius:4,width:24,height:22,cursor:idx===lista.length-1?"not-allowed":"pointer",fontSize:11,display:"flex",alignItems:"center",justifyContent:"center"}}>↓</button>
                    </div>
                  )}
                  {/* Edit toggle — líder ou gerencial */}
                  {podeEditar && (
                    <button onClick={()=>setEditId(isEditing?null:item.colabId)}
                      style={{...S.btnSm,color:isEditing?"#ef4444":"#0ea5e9",border:`1px solid ${isEditing?"#ef444433":"#0ea5e944"}`,fontSize:10,flexShrink:0}}>
                      {isEditing?"✕":"✏️"}
                    </button>
                  )}
                </div>

                {/* Férias info */}
                {!isEditing && (
                  <div style={{marginTop:10,paddingTop:10,borderTop:`1px solid ${dark?"#0f172a":"#f1f5f9"}`}}>
                    {item.dataInicio ? (
                      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                        <div>
                          <div style={{fontSize:9,...S.txtSecondary,fontWeight:700,textTransform:"uppercase",marginBottom:2}}>Início</div>
                          <div style={{fontSize:12,fontWeight:700,color:"#0ea5e9"}}>{fmtD(item.dataInicio)}</div>
                        </div>
                        <div>
                          <div style={{fontSize:9,...S.txtSecondary,fontWeight:700,textTransform:"uppercase",marginBottom:2}}>Retorno (30d)</div>
                          <div style={{fontSize:12,fontWeight:700,color:"#22c55e"}}>{fmtD(item.dataRetorno)}</div>
                        </div>
                        <div style={{gridColumn:"1/-1"}}>
                          <div style={{fontSize:9,...S.txtSecondary,fontWeight:700,textTransform:"uppercase",marginBottom:2}}>Cobertura</div>
                          <div style={{fontSize:12,...S.txtPrimary}}>{item.cobertura||<span style={{color:dark?"#334155":"#94a3b8"}}>Não definida ⚠️</span>}</div>
                        </div>
                      </div>
                    ) : (
                      <div style={{fontSize:11,...S.txtSecondary}}>
                        {podeEditar?"Toque em ✏️ para agendar férias":"Sem férias agendadas"}
                      </div>
                    )}
                    {alerta && (
                      <div style={{marginTop:8,background:alerta.tipo==="urgente"?dark?"#1a0202":"#fee2e2":dark?"#1a1000":"#fef3c7",border:`1px solid ${alerta.tipo==="urgente"?"#ef444433":"#f59e0b33"}`,borderRadius:6,padding:"5px 10px",fontSize:11,color:alerta.tipo==="urgente"?"#ef4444":"#d97706",fontWeight:700}}>
                        {alerta.msg}
                      </div>
                    )}
                  </div>
                )}

                {/* Edit form — líder ou gerencial */}
                {isEditing && podeEditar && (
                  <div style={{marginTop:10,paddingTop:10,borderTop:`1px solid ${dark?"#0f172a":"#f1f5f9"}`,display:"flex",flexDirection:"column",gap:8}}>
                    <div>
                      <label style={S.lbl}>Data de Início das Férias</label>
                      <input type="date" value={item.dataInicio}
                        onChange={e=>updateItem(item.colabId,{dataInicio:e.target.value})}
                        style={S.inp}/>
                    </div>
                    <div>
                      <label style={S.lbl}>Data de Retorno (sugestão automática: 30 dias — pode ajustar)</label>
                      <input type="date" value={item.dataRetorno}
                        onChange={e=>updateItem(item.colabId,{dataRetorno:e.target.value})}
                        style={S.inp}/>
                    </div>
                    <div>
                      <label style={S.lbl}>Cobertura (nome ou "Ferista")</label>
                      <input value={item.cobertura}
                        onChange={e=>updateItem(item.colabId,{cobertura:e.target.value})}
                        placeholder="Nome do coberturista ou Ferista..."
                        style={S.inp}/>
                    </div>
                    <div style={{display:"flex",gap:8}}>
                      <button onClick={()=>setEditId(null)} style={{...S.btnSec,flex:1,fontSize:13}}>Cancelar</button>
                      <button onClick={salvar} disabled={saving} style={{...S.btn,flex:1,fontSize:13}}>
                        {saving?"⟳ Salvando...":"✓ Salvar"}
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          })}

          {podeEditar && (
            <button onClick={salvar} disabled={saving}
              style={{...S.btnGreen||S.btn, background:"linear-gradient(135deg,#16a34a,#15803d)", color:"#fff", border:"none", borderRadius:10, padding:"13px 16px", fontSize:14, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:8}}>
              {saving?"⟳ Salvando ordem...":"💾 Salvar Ordem e Dados"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// ── Tela de PIN (entrada)
function PinScreen({ project, onSuccess, onBack, dark }) {
  const S = getStyles(dark);
  const [pin, setPin] = useState("");
  const [err, setErr] = useState(false);
  const [mode, setMode] = useState(null); // "lider" | "admin"

  const tryPin = (inputPin) => {
    if(inputPin === ADMIN_PIN) { onSuccess("admin"); return; }
    if(inputPin === PROJECT_PINS[project.id]) { onSuccess("lider"); return; }
    setErr(true);
  };

  return (
    <div style={{ ...S.page, alignItems:"center", justifyContent:"center" }}>
      <div style={{ background: dark?"#060c18":"#ffffff", border:`1px solid ${dark?"#1e293b":"#e2e8f0"}`, borderRadius:16, padding:"28px 24px", maxWidth:320, width:"100%", textAlign:"center", margin:16 }}>
        <div style={{ fontSize:32, marginBottom:8 }}>👥</div>
        <div style={{ fontSize:16, fontWeight:800, ...S.txtPrimary, marginBottom:4 }}>Equipe — {project.id}</div>
        <div style={{ fontSize:12, ...S.txtSecondary, marginBottom:20 }}>{project.name}</div>

        {!mode && (
          <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            <button onClick={()=>setMode("lider")}
              style={{ ...S.btn, background:"linear-gradient(135deg,#0369a1,#0c4a6e)", fontSize:13 }}>
              👷 Acesso Líder
            </button>
            <button onClick={()=>setMode("admin")}
              style={{ ...S.btnSec, fontSize:13, color:"#f59e0b", borderColor:"#f59e0b33" }}>
              🔐 Acesso Gerencial
            </button>
            <button onClick={onBack} style={{ ...S.btnSec, fontSize:13, marginTop:4 }}>← Voltar</button>
          </div>
        )}

        {mode && (
          <>
            <div style={{ fontSize:12, ...S.txtSecondary, marginBottom:12 }}>
              {mode==="lider"?"PIN do projeto":"PIN gerencial"}
            </div>
            <input type="password" inputMode="numeric" placeholder="PIN" maxLength={8} value={pin}
              onChange={e=>{ setPin(e.target.value); setErr(false); }}
              onKeyDown={e=>{ if(e.key==="Enter") tryPin(pin); }}
              style={{ ...S.inp, textAlign:"center", fontSize:22, letterSpacing:10, marginBottom:8 }}/>
            {err && <div style={{ fontSize:12, color:"#ef4444", marginBottom:8 }}>PIN incorreto</div>}
            <div style={{ display:"flex", gap:8 }}>
              <button onClick={()=>{ setMode(null); setPin(""); setErr(false); }} style={{ ...S.btnSec, flex:1, fontSize:13 }}>← Voltar</button>
              <button onClick={()=>tryPin(pin)} style={{ ...S.btn, flex:1, fontSize:13 }}>Entrar</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// ── App principal
export default function EquipeApp({ project, onBack, dark: darkProp, onToggleTheme, sharedAuth, onAuthGranted }) {
  const [equipeData, setEquipeData] = useState({ colaboradores:[], desligados:[] });
  const [screen, setScreen] = useState(()=>(sharedAuth||getAccess(project?.id))?"list":"pin"); // pin | list | add | edit | view | addHist
  // Keyframe do "piscar" de reciclagem — injeta uma vez no documento.
  useEffect(()=>{
    if(typeof document==="undefined") return;
    if(document.getElementById("recPiscaKF")) return;
    const st=document.createElement("style");
    st.id="recPiscaKF";
    st.textContent="@keyframes recPiscaAnim{0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,0);}50%{box-shadow:0 0 0 3px rgba(239,68,68,.45);}}";
    document.head.appendChild(st);
  },[]);
  const [authLevel, setAuthLevel] = useState(()=>sharedAuth||getAccess(project?.id)||null); // null | "lider" | "admin"
  const [selColab, setSelColab] = useState(null);
  const [form, setForm] = useState(null);
  const [histForm, setHistForm] = useState({ tipo:"Falta", data:todayStr(), detalhe:"" });
  const [showDesligados, setShowDesligados] = useState(false);
  const [selPDF, setSelPDF] = useState([]); // ids selecionados para PDF
  const [modoSel, setModoSel] = useState(false); // modo seleção PDF
  const [editHistItem, setEditHistItem] = useState(null); // item do histórico em edição
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [darkLocal, setDarkLocal] = useState(true);
  const dark = darkProp !== undefined ? darkProp : darkLocal;
  const toggleDark = onToggleTheme || (()=>setDarkLocal(!darkLocal));

  const S = getStyles(dark);
  const adminAuth = authLevel === "admin";
  const liderAuth = authLevel === "lider" || authLevel === "admin";
  const cargos = CARGOS_PROJETO[project.id] || ["Colaborador"];

  useEffect(() => {
    loadEquipe(project.id).then(data => {
      setEquipeData(data || { colaboradores:[], desligados:[] });
      setLoading(false);
    });
  }, [project.id]);

  const save = async (newData) => {
    setSaving(true);
    setEquipeData(newData);
    await saveEquipe(project.id, newData);
    setSaving(false);
  };

  const setF = (k,v) => setForm(f=>({...f,[k]:v}));

  const saveColab = async () => {
    if(!form.nome.trim()) { alert("Informe o nome"); return; }
    if(!liderAuth) { alert("Acesso negado"); return; }
    setSaving(true);
    try {
      // Comprime foto para max 400px e qualidade 0.7 antes de salvar
      let fotoFinal = "";
      if(form.foto && form.foto.startsWith("data:")) {
        fotoFinal = await new Promise((resolve) => {
          const img = new Image();
          img.onload = () => {
            // Compress agressively: max 300px, 60% quality
            const MAX = 300;
            let w = img.width, h = img.height;
            if(w > h && w > MAX) { h = Math.round(h*MAX/w); w = MAX; }
            else if(h >= w && h > MAX) { w = Math.round(w*MAX/h); h = MAX; }
            const canvas = document.createElement("canvas");
            canvas.width = w; canvas.height = h;
            const ctx = canvas.getContext("2d");
            ctx.drawImage(img, 0, 0, w, h);
            const compressed = canvas.toDataURL("image/jpeg", 0.6);
            // Safety check: if still > 80KB, compress more
            if(compressed.length > 80*1024) {
              const canvas2 = document.createElement("canvas");
              const s = Math.min(w,h,200);
              canvas2.width = s; canvas2.height = s;
              canvas2.getContext("2d").drawImage(img,0,0,s,s);
              resolve(canvas2.toDataURL("image/jpeg", 0.5));
            } else {
              resolve(compressed);
            }
          };
          img.onerror = () => resolve("");
          img.src = form.foto;
        });
      }
      const formFinal = { ...form, foto: fotoFinal };
      // Remove campos undefined para não quebrar Firestore
      Object.keys(formFinal).forEach(k => { if(formFinal[k]===undefined) formFinal[k]=""; });
      // Limpa campos de Falta que não existem em outros tipos
      if(formFinal.subtipo===undefined) formFinal.subtipo="";
      if(formFinal.dataFim===undefined) formFinal.dataFim="";
      const isNew = !equipeData.colaboradores.find(c=>c.id===form.id);
      const newColabs = isNew
        ? [...equipeData.colaboradores, formFinal]
        : equipeData.colaboradores.map(c=>c.id===form.id?formFinal:c);
      const newData = {...equipeData, colaboradores:newColabs};
      setEquipeData(newData);
      await saveEquipe(project.id, newData);
      setSaving(false);
      setScreen("list");
      setForm(null);
    } catch(err) {
      console.error("Erro ao salvar colaborador:", err);
      setSaving(false);
      // Try saving without photo as fallback
      try {
        const formSemFoto = { ...form, foto: "" };
        Object.keys(formSemFoto).forEach(k => { if(formSemFoto[k]===undefined) formSemFoto[k]=""; });
        const isNew = !equipeData.colaboradores.find(c=>c.id===form.id);
        const newColabs = isNew
          ? [...equipeData.colaboradores, formSemFoto]
          : equipeData.colaboradores.map(c=>c.id===form.id?formSemFoto:c);
        const newData = {...equipeData, colaboradores:newColabs};
        setEquipeData(newData);
        await saveEquipe(project.id, newData);
        setSaving(false);
        setScreen("list");
        setForm(null);
        alert("Salvo sem foto (limite de armazenamento atingido).");
      } catch(err2) {
        console.error("Fallback save also failed:", err2);
        alert("Erro ao salvar. Verifique sua conexão e tente novamente.");
      }
    }
  };

  const addHistorico = async () => {
    if(!histForm.data) { alert("Informe a data"); return; }
    if(histForm.tipo==="Medida Disciplinar" && !histForm.detalhe) { alert("Especifique o tipo de medida"); return; }
    if(histForm.tipo==="Falta" && histForm.subtipo==="Período" && !histForm.dataFim) { alert("Informe a data fim"); return; }
    // Enrich falta entry
    let extra = {};
    if(histForm.tipo==="Falta") {
      if(histForm.subtipo==="Período" && histForm.dataFim) {
        const dias = Math.round((new Date(histForm.dataFim)-new Date(histForm.data))/86400000)+1;
        extra = { diasFalta:dias, label:`${dias} dia(s) — ${fmtDate(histForm.data)} a ${fmtDate(histForm.dataFim)}` };
      } else if(histForm.subtipo==="Indeterminado") {
        extra = { indeterminado:true, emAberto:true, label:`Afastamento indeterminado desde ${fmtDate(histForm.data)}` };
      } else {
        extra = { diasFalta:1, subtipo:"1 dia", label:fmtDate(histForm.data) };
      }
    }
    const item = { ...histForm, ...extra, id:Date.now().toString(), registradoEm:new Date().toISOString() };
    const newColabs = equipeData.colaboradores.map(c=>{
      if(c.id!==selColab.id) return c;
      const newHist = [item, ...(c.historico||[])];
      const afastamentoAberto = (histForm.tipo==="Falta"&&histForm.subtipo==="Indeterminado") ? item.id : (c.afastamentoAberto||null);
      return {...c, historico:newHist, afastamentoAberto};
    });
    const updated = {...equipeData, colaboradores:newColabs};
    await save(updated);
    setSelColab(newColabs.find(c=>c.id===selColab.id));
    setHistForm({tipo:"Falta",data:todayStr(),detalhe:""});
    setScreen("view");
  };

  const removeHist = async (colabId, histId) => {
    if(!adminAuth) return;
    const newColabs = equipeData.colaboradores.map(c=>{
      if(c.id!==colabId) return c;
      return {...c, historico:(c.historico||[]).filter(h=>h.id!==histId)};
    });
    const updated = {...equipeData, colaboradores:newColabs};
    await save(updated);
    setSelColab(newColabs.find(c=>c.id===colabId));
  };

  const saveEditHist = async (colabId, histId, updatedFields, isLider) => {
    const newColabs = equipeData.colaboradores.map(c => {
      if(c.id !== colabId) return c;
      const newHist = (c.historico||[]).map(h => {
        if(h.id !== histId) return h;
        return {
          ...h,
          ...updatedFields,
          editadoPor: isLider ? "lider" : "gerencial",
          editadoEm: new Date().toISOString(),
        };
      });
      return {...c, historico: newHist};
    });
    const newData = {...equipeData, colaboradores: newColabs};
    setEquipeData(newData);
    // Update selColab if it's the one being edited
    const updated = newColabs.find(c=>c.id===colabId);
    if(updated) setSelColab(updated);
    await saveEquipe(project.id, newData);
    setEditHistItem(null);
    setScreen("view");
  };

  const desligarColab = async (colab, motivo, tipoDeslig, dataDeslig) => {
    if(!adminAuth) return;
    const desligado = {
      ...colab,
      status:"desligado",
      desligadoEm: dataDeslig || todayStr(),
      motivoDesligamento: motivo || "",
      tipoDesligamento: tipoDeslig || "Demissão"
    };
    const newColabs = equipeData.colaboradores.filter(c=>c.id!==colab.id);
    const newDesligados = [desligado, ...(equipeData.desligados||[])];
    await save({...equipeData, colaboradores:newColabs, desligados:newDesligados});
    setScreen("list"); setSelColab(null);
  };

  const reativarColab = async (colab) => {
    if(!adminAuth) return;
    const reativado = {...colab, status:"ativo", desligadoEm:null, motivoDesligamento:undefined, tipoDesligamento:undefined};
    const newDesligados = (equipeData.desligados||[]).filter(c=>c.id!==colab.id);
    await save({...equipeData, colaboradores:[...equipeData.colaboradores, reativado], desligados:newDesligados});
  };

  const excluirDesligado = async (colab) => {
    if(!adminAuth) return;
    const newDesligados = (equipeData.desligados||[]).filter(c=>c.id!==colab.id);
    await save({...equipeData, desligados:newDesligados});
  };

  if(loading) return (
    <div style={{...S.page,alignItems:"center",justifyContent:"center"}}>
      <div style={{textAlign:"center"}}>
        <div style={{fontSize:30,marginBottom:10}}>👥</div>
        <div style={{fontSize:13,color:"#64748b"}}>Carregando equipe...</div>
      </div>
    </div>
  );

  // ── PIN
  if(screen==="pin") return (
    <PinScreen project={project} dark={dark}
      onBack={onBack}
      onSuccess={(level)=>{ grantSession(level, project.id); setAuthLevel(level); setScreen("list"); onAuthGranted?.(level); }}/>
  );

  // ── Formulário: cadastro (líder ou admin) / edição (admin only)
  if(screen==="add"&&form&&liderAuth) return (
    <FormScreen form={form} setF={setF} cargos={cargos} onSave={saveColab}
      onCancel={()=>{setScreen("list");setForm(null);}} saving={saving} isEdit={false} dark={dark}/>
  );
  if(screen==="editHist"&&editHistItem) return (
    <EditHistScreen
      item={editHistItem}
      isLider={!adminAuth}
      onSave={(updatedFields)=>saveEditHist(selColab.id, editHistItem.id, updatedFields, !adminAuth)}
      onCancel={()=>{setEditHistItem(null);setScreen("view");}}
      dark={dark}/>
  );
  if(screen==="ferias") return (
    <ProjecaoFerias
      project={project}
      colaboradores={(equipeData.colaboradores||[]).filter(c=>c.status==="ativo")}
      adminAuth={adminAuth}
      liderAuth={liderAuth}
      onBack={()=>setScreen("list")}
      onSave={async(ferias)=>{
        const newData = {...equipeData, ferias};
        setEquipeData(newData);
        await saveEquipe(project.id, newData);
      }}
      ferias={equipeData.ferias||[]}
      dark={dark}
      onToggleTheme={toggleDark}/>
  );
  if(screen==="edit"&&form&&liderAuth) return (
    <FormScreen form={form} setF={setF} cargos={cargos} onSave={saveColab}
      onCancel={()=>{setScreen("view");setForm(null);}} saving={saving} isEdit={true} dark={dark}/>
  );

  // ── Adicionar histórico (líder ou admin)
  if(screen==="addHist"&&selColab) return (
    <AddHistScreen colabNome={selColab.nome} histForm={histForm} setHistForm={setHistForm}
      onSave={addHistorico} onCancel={()=>setScreen("view")} dark={dark}/>
  );

  // ── Ficha
  if(screen==="view"&&selColab) {
    const colab = equipeData.colaboradores.find(c=>c.id===selColab.id) || selColab;
    return (
      <FichaScreen colab={colab} adminAuth={adminAuth} liderAuth={liderAuth} dark={dark}
        onBack={()=>{setScreen("list");setSelColab(null);}}
        onEdit={()=>{setForm({...colab});setScreen("edit");}}
        onAddHist={()=>setScreen("addHist")}
        onEditHist={(colabId, item)=>{setEditHistItem(item);setScreen("editHist");}}
        onDesligar={desligarColab}
        onRemoveHist={removeHist}/>
    );
  }

  // ── Lista principal
  const ativos = equipeData.colaboradores.filter(c=>c.status==="ativo");
  const desligados = equipeData.desligados || [];
  const turnosComEquipe = getTurnos(project.id).filter(t => ativos.some(c=>c.turno===t));
  const semTurno = ativos.filter(c=>!getTurnos(project.id).includes(c.turno));

  return (
    <div style={S.page}>
      <div style={S.wrap}>
        <Header
          title="Equipe"
          sub={`${project.id} · ${project.name} · ${ativos.length} ativo(s)`}
          onBack={onBack}
          saving={saving}
          dark={dark}
          onToggleTheme={toggleDark}
        />

        <div style={{ padding:"12px 16px", display:"flex", flexDirection:"column", gap:10 }}>

          {/* Barra de auth */}
          {adminAuth ? (
            <div style={{ background:"#021a0d", border:"1px solid #22c55e33", borderRadius:10, padding:"10px 14px" }}>
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom: modoSel?8:0 }}>
                <div style={{ fontSize:12, color:"#22c55e", fontWeight:700 }}>🔓 Modo Gerencial Ativo</div>
                <div style={{ display:"flex", gap:6 }}>
                  <button onClick={()=>{ setModoSel(!modoSel); setSelPDF([]); }}
                    style={{ ...S.btnSm, color: modoSel?"#f59e0b":"#22c55e", border:`1px solid ${modoSel?"#f59e0b44":"#22c55e44"}`, fontSize:10, padding:"4px 10px" }}>
                    {modoSel?"✕ Cancelar":"📄 Exportar PDF"}
                  </button>
                  <button onClick={()=>setScreen("ferias")}
                    style={{ ...S.btnSm, color:"#0ea5e9", border:"1px solid #0ea5e944", fontSize:10, padding:"4px 10px" }}>
                    🏖️ Férias
                  </button>
                  <button onClick={()=>{clearSession();setAuthLevel(null);setScreen("pin");}} style={{ ...S.btnSm, color:"#64748b", fontSize:10 }}>Sair</button>
                </div>
              </div>
              {modoSel&&(
                <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                  <button onClick={()=>{ const ids=ativos.map(c=>c.id); setSelPDF(ids); }}
                    style={{ ...S.btnSm, fontSize:10, color:"#0ea5e9", border:"1px solid #0ea5e944", padding:"4px 10px" }}>
                    ☐ Todos ({ativos.length})
                  </button>
                  {getTurnos(project.id).map(t=>{
                    const cols=ativos.filter(c=>c.turno===t);
                    if(!cols.length) return null;
                    return(
                      <button key={t} onClick={()=>{ const ids=cols.map(c=>c.id); setSelPDF(ids); }}
                        style={{ ...S.btnSm, fontSize:10, color:"#94a3b8", border:"1px solid #1e293b", padding:"4px 10px" }}>
                        {t} ({cols.length})
                      </button>
                    );
                  })}
                  {selPDF.length>0&&(
                    <button onClick={()=>{
                      const cols = ativos.filter(c=>selPDF.includes(c.id));
                      const titulo = selPDF.length===1
                        ? cols[0].nome
                        : selPDF.length===ativos.length
                        ? `Equipe Completa — ${project.id}`
                        : `Seleção — ${project.id}`;
                      gerarMapaEquipePDF(project, cols, titulo);
                    }}
                      style={{ ...S.btnSm, fontSize:10, color:"#fff", background:"linear-gradient(135deg,#7c3aed,#6d28d9)", border:"none", padding:"5px 14px", fontWeight:700 }}>
                      📄 Gerar PDF ({selPDF.length})
                    </button>
                  )}
                </div>
              )}
            </div>
          ) : liderAuth ? (
            <div style={{ background:"#001a2e", border:"1px solid #0ea5e933", borderRadius:10, padding:"10px 14px", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
              <div style={{ fontSize:12, color:"#0ea5e9", fontWeight:700 }}>👷 Acesso Líder — Pode adicionar registros</div>
              <div style={{ display:"flex", gap:6 }}>
                <button onClick={()=>setScreen("ferias")}
                  style={{ ...S.btnSm, color:"#0ea5e9", border:"1px solid #0ea5e944", fontSize:10, padding:"4px 10px" }}>
                  🏖️ Férias
                </button>
                <button onClick={()=>{clearSession();setAuthLevel(null);setScreen("pin");}} style={{ ...S.btnSm, color:"#64748b", fontSize:10 }}>Sair</button>
              </div>
            </div>
          ) : null}

          {/* Botão cadastrar — líder ou admin */}
          {liderAuth && (
            <button onClick={()=>{setForm(emptyColab(cargos[0],project.id,"Diurno"));setScreen("add");}}
              style={{ ...S.btn, fontSize:13 }}>
              + Cadastrar Colaborador
            </button>
          )}

          {/* Resumo por turno */}
          {turnosComEquipe.length > 0 && (
            <div style={{ display:"grid", gridTemplateColumns:`repeat(${turnosComEquipe.length},1fr)`, gap:6 }}>
              {turnosComEquipe.map(t=>{
                const tc = TURNO_CONFIG[t];
                const count = ativos.filter(c=>c.turno===t).length;
                return (
                  <div key={t} style={{ background:tc.bg, border:`1px solid ${tc.border}`, borderRadius:10, padding:"10px 12px", textAlign:"center" }}>
                    <div style={{ fontSize:18, marginBottom:3 }}>{tc.icon}</div>
                    <div style={{ fontSize:12, fontWeight:700, color:tc.badge }}>{t}</div>
                    <div style={{ fontSize:11, color:"#64748b", marginTop:2 }}>{count}</div>
                  </div>
                );
              })}
            </div>
          )}

          {/* Cards por turno */}
          {getTurnos(project.id).map(turno=>{
            const tc = TURNO_CONFIG[turno];
            const colabsDoTurno = ativos.filter(c=>c.turno===turno);
            if(colabsDoTurno.length===0 && !adminAuth) return null;
            return (
              <div key={turno} style={{ borderRadius:12, overflow:"hidden", border:`1px solid ${tc.border}` }}>
                <div style={{ background:tc.bg, padding:"10px 14px", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                    <span style={{ fontSize:16 }}>{tc.icon}</span>
                    <span style={{ fontSize:13, fontWeight:700, color:tc.badge }}>{turno}</span>
                    <span style={{ fontSize:10, color:"#64748b", background:"#0a0f1e", padding:"2px 8px", borderRadius:10 }}>{colabsDoTurno.length}</span>
                  </div>
                  {liderAuth && (
                    <button onClick={()=>{setForm(emptyColab(cargos[0],project.id,turno));setScreen("add");}}
                      style={{ ...S.btnSm, fontSize:10, color:tc.badge, border:`1px solid ${tc.badge}44`, padding:"4px 10px" }}>
                      + Adicionar
                    </button>
                  )}
                </div>
                <div style={{ background: dark?"#04080f":"#f8fafc", padding:"8px" }}>
                  {colabsDoTurno.length===0 && (
                    <div style={{ textAlign:"center", padding:"14px 0", fontSize:11, color:"#334155" }}>
                      {adminAuth?"Nenhum cadastrado — toque em + Adicionar":"Nenhum cadastrado"}
                    </div>
                  )}
                  <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                    {colabsDoTurno.map(c=>{
                      const recPisca = reciclagemPisca(c.ultimaReciclagem);
                      const recEstado = statusReciclagem(c.ultimaReciclagem).estado;
                      const faltas = (c.historico||[]).filter(h=>h.tipo==="Falta").length;
                      const fts    = (c.historico||[]).filter(h=>h.tipo==="FT").length;
                      const mds    = (c.historico||[]).filter(h=>h.tipo==="Medida Disciplinar").length;
                      return (
                        <div key={c.id}
                          style={{ display:"flex", alignItems:"center", gap:10, background: dark?"#060c18":"#ffffff", borderRadius:10, padding:"10px 12px", cursor:"pointer",
                            border:`2px solid ${modoSel&&selPDF.includes(c.id)?"#7c3aed":recPisca?(recEstado==="vencido"?"#ef4444":"#f59e0b"):tc.border}`,
                            animation: recPisca ? "recPiscaAnim 1.1s ease-in-out infinite" : "none" }}
                          onClick={()=>{ if(modoSel){ setSelPDF(prev=>prev.includes(c.id)?prev.filter(id=>id!==c.id):[...prev,c.id]); } else { setSelColab(c);setScreen("view"); } }}>
                          {modoSel&&(
                            <div style={{ width:22,height:22,borderRadius:5,border:`2px solid ${selPDF.includes(c.id)?"#7c3aed":"#1e293b"}`,background:selPDF.includes(c.id)?"#7c3aed22":"transparent",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,color:"#a78bfa" }}>
                              {selPDF.includes(c.id)&&"✓"}
                            </div>
                          )}
                          <Avatar foto={c.foto} size={46} border={tc.badge+"44"}/>
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ fontSize:13, fontWeight:700, ...S.txtPrimary, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{c.nome}</div>
                            <div style={{ fontSize:11, ...S.txtSecondary, marginTop:1 }}>{c.cargo}</div>
                            {coberturaAtiva(c) && <div style={{fontSize:9,fontWeight:800,color:"#0ea5e9",background:"#001a2e",border:"1px solid #0ea5e944",padding:"1px 7px",borderRadius:5,display:"inline-block",marginTop:3}}>🔁 Cobrindo Líder até {fmtDate(c.coberturaFim)}</div>}
                            <div style={{ display:"flex", gap:5, marginTop:4, flexWrap:"wrap" }}>
                              {c.escala && <span style={{ fontSize:9, color:"#0ea5e9", background:"#001a2e", padding:"1px 6px", borderRadius:4, fontWeight:700 }}>{c.escala}</span>}
                              {c.telefone && <span style={{ fontSize:9, color:"#94a3b8", padding:"1px 5px" }}>📱 {c.telefone}</span>}
                              {recPisca && <span style={{ fontSize:9, fontWeight:800, color:recEstado==="vencido"?"#ef4444":"#f59e0b", background:(recEstado==="vencido"?"#ef4444":"#f59e0b")+"22", padding:"1px 6px", borderRadius:4 }}>🔄 {reciclagemLabel(c.ultimaReciclagem)}</span>}
                            </div>
                          </div>
                          <div style={{ flexShrink:0, textAlign:"right" }}>
                            {faltas>0 && <div style={{ fontSize:9, color:"#ef4444", fontWeight:700 }}>{faltas}F</div>}
                            {fts>0    && <div style={{ fontSize:9, color:"#f59e0b", fontWeight:700 }}>{fts}FT</div>}
                            {mds>0    && <div style={{ fontSize:9, color:"#a855f7", fontWeight:700 }}>{mds}MD</div>}
                            <span style={{ color:"#334155", fontSize:14, display:"block", marginTop:2 }}>›</span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            );
          })}

          {/* Sem turno */}
          {semTurno.length > 0 && (
            <div style={S.card}>
              <div style={{ fontSize:12, fontWeight:700, color:"#64748b", marginBottom:8 }}>Sem turno ({semTurno.length})</div>
              {semTurno.map(c=>(
                <div key={c.id} onClick={()=>{setSelColab(c);setScreen("view");}}
                  style={{ display:"flex", alignItems:"center", gap:10, background:"#020510", borderRadius:8, padding:"10px 12px", cursor:"pointer", marginBottom:6, border:"1px solid #0a0f1e" }}>
                  <Avatar foto={c.foto} size={42}/>
                  <div style={{ flex:1 }}>
                    <div style={{ fontSize:13, fontWeight:700, ...S.txtPrimary }}>{c.nome}</div>
                    <div style={{ fontSize:11, ...S.txtSecondary }}>{c.cargo}</div>
                  </div>
                  <span style={{ color:"#334155", fontSize:14 }}>›</span>
                </div>
              ))}
            </div>
          )}

          {/* Desligados */}
          {desligados.length > 0 && (
            <div style={S.card}>
              <button onClick={()=>setShowDesligados(!showDesligados)}
                style={{ width:"100%", background:"transparent", border:"none", display:"flex", alignItems:"center", justifyContent:"space-between", cursor:"pointer", padding:0 }}>
                <span style={{ fontSize:12, fontWeight:700, color:"#ef4444" }}>🔴 Desligados ({desligados.length})</span>
                <span style={{ color:"#334155", fontSize:12 }}>{showDesligados?"▲":"▼"}</span>
              </button>
              {showDesligados && (
                <div style={{ marginTop:10, display:"flex", flexDirection:"column", gap:6 }}>
                  {desligados.map(c=>(
                    <div key={c.id} style={{ background:"#1a0202", borderRadius:10, padding:"10px 12px", border:"1px solid #ef444422", marginBottom:6 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                        <Avatar foto={c.foto} size={40} border="#ef444444"/>
                        <div style={{ flex:1 }}>
                          <div style={{ fontSize:12, fontWeight:700, color:"#94a3b8" }}>{c.nome}</div>
                          <div style={{ fontSize:10, color:"#475569" }}>{c.cargo}</div>
                          <div style={{ display:"flex", gap:6, marginTop:3, flexWrap:"wrap" }}>
                            {c.tipoDesligamento&&<span style={{ fontSize:9, color:"#ef4444", background:"#2a0202", padding:"1px 6px", borderRadius:4, fontWeight:700 }}>{c.tipoDesligamento}</span>}
                            {c.desligadoEm&&<span style={{ fontSize:9, color:"#64748b" }}>📅 {fmtDate(c.desligadoEm)}</span>}
                          </div>
                          {c.motivoDesligamento&&<div style={{ fontSize:10, color:"#64748b", marginTop:2, fontStyle:"italic" }}>{c.motivoDesligamento}</div>}
                        </div>
                        {adminAuth && (
                          <div style={{ display:"flex", flexDirection:"column", gap:4, flexShrink:0 }}>
                            <button onClick={()=>reativarColab(c)}
                              style={{ ...S.btnSm, color:"#22c55e", border:"1px solid #22c55e44", fontSize:10, padding:"4px 10px" }}>
                              ↑ Reativar
                            </button>
                            <button onClick={()=>{
                              if(window.confirm(`Excluir permanentemente ${c.nome}?

Esta ação não pode ser desfeita.`))
                                excluirDesligado(c);
                            }}
                              style={{ ...S.btnSm, color:"#ef4444", border:"1px solid #ef444433", fontSize:10, padding:"4px 10px" }}>
                              🗑 Excluir
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {ativos.length === 0 && (
            <div style={{ textAlign:"center", padding:"40px 0" }}>
              <div style={{ fontSize:40, marginBottom:10 }}>👥</div>
              <div style={{ fontSize:14, ...S.txtPrimary, marginBottom:4 }}>Equipe vazia</div>
              <div style={{ fontSize:12, ...S.txtSecondary }}>
                {liderAuth?"Toque em + Cadastrar Colaborador para começar":"Acesso necessário para cadastrar colaboradores"}
              </div>
            </div>
          )}

          <div style={{ fontSize:10, color:"#1e293b", textAlign:"center", marginTop:4 }}>
            Líder: adicionar FT/Falta/Medida · Gerencial: cadastrar, editar, desligar
          </div>
        </div>
      </div>
    </div>
  );
}
